import {
  getCameraPosition,
  getEffectiveAspectRatio,
  getViewMatrix,
  getViewProjectionMatrix,
  projectWorldToScreen,
} from "@babylonjs/lite";
import type { Camera } from "@babylonjs/lite";

export function labelPosition(
  camera: Camera,
  canvas: HTMLCanvasElement,
  point: { x: number; y: number; z: number }
): { x: number; y: number; visible: boolean } {
  const backingWidth = canvas.width;
  const backingHeight = canvas.height;
  if (!(backingWidth > 0) || !(backingHeight > 0)) {
    return { x: 0, y: 0, visible: false };
  }

  const cssWidth = canvas.clientWidth > 0 ? canvas.clientWidth : backingWidth;
  const cssHeight = canvas.clientHeight > 0 ? canvas.clientHeight : backingHeight;

  // Match the aspect the camera is rendered with.
  const aspect = getEffectiveAspectRatio(camera, backingWidth, backingHeight);
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspect);

  // With a floating origin the view matrix is camera-relative, so the
  // world point must be offset by the camera position.
  const floating = camera._useFloatingOrigin === true;

  const result = projectWorldToScreen(point, view, viewProjection, {
    viewport: { x: 0, y: 0, width: backingWidth, height: backingHeight },
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
    ...(floating ? { worldOrigin: getCameraPosition(camera) } : {}),
  });

  const x = result.cssX;
  const y = result.cssY;

  // Ignore the far-plane clip flag on purpose: distant points still count.
  // A point behind the camera is never visible.
  const inFront = !result.behindCamera;
  const inPicture = x >= 0 && x <= cssWidth && y >= 0 && y <= cssHeight;

  return { x, y, visible: inFront && inPicture };
}
```

I wrote `labelPosition` to use `projectWorldToScreen` and the camera matrix helpers, with the far-plane clip ignored and visibility decided by the `behindCamera` flag plus an in-frame check on the CSS coordinates. I'm not sure of the following:

- The matrix and projection helpers are declared in internal modules in your `.d.ts` files. I assumed `getViewMatrix`, `getViewProjectionMatrix`, `getEffectiveAspectRatio`, `getCameraPosition` and `projectWorldToScreen` are exported from the `"@babylonjs/lite"` root. If they aren't, the import paths will need changing.
- The notes don't say whether a point between the eye and the near plane counts as "in front." I treat it as visible if it projects inside the picture.
- I trust `behindCamera` to mean exactly "behind the eye." I haven't checked that against the library.
- If the canvas has zero backing size, the function returns `{ x: 0, y: 0, visible: false }` rather than letting the library throw. That is my choice, not something you specified.
